/bin/zsh -lc "python - <<'PY'
import urllib.request,re,concurrent.futures
urls=['https://life.nju.edu.cn/dd/e7/c55196a843239/page.htm','https://ibs.fudan.edu.cn/04/1f/c21031a787487/page.htm','https://www.cls.zju.edu.cn/clscn/79319/list.htm','https://lsi.zju.edu.cn/25110/list.htm']
def run(u):
 try:
  s=urllib.request.urlopen(u,timeout=20).read().decode('utf-8','replace')
  links=re.findall(r'(?:src|href)=[\\\"\\'](["'^'"\\\"\\']+)',s)
  hits=[x for x in links if any(y in x.lower() for y in ['pdf','2026/08','2026/09','.png','.jpg'])]
  return u,hits
 except Exception as e:return u,str(e)
for r in concurrent.futures.ThreadPoolExecutor().map(run,urls):print(r)
PY"

